async function seed() {
  console.log(`Seeding ${materials.length} raw materials...`);

  // Clear existing materials for a clean seed
  await db.execute(sql`TRUNCATE TABLE materials RESTART IDENTITY CASCADE`);

  // Insert in batches of 50
  const BATCH = 50;
  let inserted = 0;
  for (let i = 0; i < materials.length; i += BATCH) {
    const batch = materials.slice(i, i + BATCH);
    await db.insert(materialsTable).values(batch);
    inserted += batch.length;
    console.log(`  ✓ ${inserted}/${materials.length}`);
  }

  console.log(`\nDone. ${materials.length} materials seeded.`);
  await pool.end();
}

seed().catch((err) => {
  console.error(err);
  process.exit(1);
});
